import { DevNullLogger } from '@went.tf/discord-bot-framework/logger';
import { ChatInputCommandInteraction } from 'discord.js';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { backendApiRequest } from './backend-api-request.js';
import { sendCommandTelemetry } from './backend-api-data-updaters.js';

// typia validators are generated by a TypeScript transform that vitest does not run
vi.mock('typia', () => ({ default: { createValidate: () => () => ({ success: true }) } }));

vi.mock('./backend-api-request.js', () => ({
  backendApiRequest: vi.fn(async () => ({ ok: true, status: 200, response: { executionNumber: 3, commandName: 'at', commandId: '1', privacyPolicyUrl: 'x' } })),
}));

const interaction = { locale: 'en-US', commandId: '1', options: { data: [{ name: 'hour', type: 3 }] } } as unknown as ChatInputCommandInteraction;
const context = (extra: { commandRecordedByApi?: boolean; telemetry?: boolean } = {}) => ({
  logger: new DevNullLogger(),
  getSettings: async () => ({ telemetry: extra.telemetry ?? true }) as never,
  commandRecordedByApi: extra.commandRecordedByApi,
});

describe('sendCommandTelemetry', () => {
  beforeEach(() => {
    vi.mocked(backendApiRequest).mockClear();
  });

  it('records a run, as before', async () => {
    const result = await sendCommandTelemetry(context(), interaction);

    expect(backendApiRequest).toHaveBeenCalledTimes(1);
    expect(result).toMatchObject({ executionNumber: 3 });
  });

  it('does not record a run the API recorded already, so it is not counted twice', async () => {
    const result = await sendCommandTelemetry(context({ commandRecordedByApi: true }), interaction);

    expect(backendApiRequest).not.toHaveBeenCalled();
    // null means "nothing to add to the reply", which is right since the API put the note there
    expect(result).toBeNull();
  });

  it('still respects an account that opted out', async () => {
    expect(await sendCommandTelemetry(context({ telemetry: false }), interaction)).toBeNull();
    expect(backendApiRequest).not.toHaveBeenCalled();
  });
});
